#define C(a,b,c) cross(a.xyz-d.xyz,b.xyz-d.xyz).z*cross(c.xyz-d.xyz,b.xyz-d.xyz).z>0.

vec4 hash(float p)
{
	vec4 p4 = fract(vec4(p) * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);

}

float L(vec2 a, vec2 b, vec2 p){
        b-=a; p-=a;
        return length(p - b * clamp(dot(p,b)/dot(b,b), 0., 1.));
}


void mainImage(out vec4 O, vec2 U)
{
        O = vec4(.7);
        vec3 R = iResolution,u,uu;
        u.xy = .3*(U+U - R.xy)/ R.y; u.x += R.x/R.y*.6;
        u.xy += .1*vec2(cos(iTime*.2),sin(iTime*.4));
        vec4 a,b,c,d,e,aa,bb,cc;
        c.y = 1.; b=-c; a.x = tan(6.28/5.);
        float i,T,tt, h,g=sqrt(5.)*.5-.5,k = a.x   ;
        //h=9.;
        for(i=0.;i<11.;i++){
                //if(T<.5){a.w++;b.w++;  }
                //else    {a.w++;c.w++;           }


                //a.w++;b.w++,c.w++;

                if(i<10.){aa=a;bb=b;cc=c;tt=T,uu=u;}
                d.xy = a.xy + (b.xy-a.xy)*g;

                //if(T<.5){a.w++;c.w++;  }
                //else    {a.w++;b.w++;           }



                ////a.w++;b.w++,c.w++;
                if(T>.5)
                        if(C(a,c,u)) {
                                b=c,c=d, T--;
                                //a.w++;b.w++,c.w++;//       
                                //a.w=b.w=c.w=0.;
                                //c.w++;
                        }else{  
                                a=b,b=c,c=d;
                        }
                else{        
                e.xy = c.xy +(a.xy-c.xy)*g;
                //e = a+(c-a)*g*g;
                        if(C(a,e,u)){
                                b=d,c=e, T++;    
                                //a.w++;b.w++,c.w++;//       
                                //a.w=b.w=c.w=0.;
                                //b.w++;
                        }else if( C(b,c,u)){
                                a=c, c=b, b=d;
                        }else{
                                a=c, b=d, c=e;
                        }

                }

                a.w++;b.w++,c.w++;
                //if(T>.5){a.w++;b.w++;  }
                //else    {a.w++;c.w++;           }



        }
        //O = vec4( length(;
        //if(T>.5)e=c,c=b,b=e;
        //T=tt, a.xy=aa.xy;b.xy=bb.xy,c.xy=cc.xy;u=uu;

        a.w=aa.w; b.w=bb.w,c.w=cc.w;

        //k=pow(2.,i);

        float clr ;//, bb=b.z ,cc=c.z; a.z=b.z=c.z=0.;

        if(T>.5){
                h = L(a.xy,b.xy,u.xy), i = length(u-c.xyz)-g*g*length(a.xyz-c.xyz);
                clr = a.w;//-c.w-b.w;
        }else{
                h = L(a.xy,c.xy,u.xy), i = length(u-b.xyz)-g*  length(c.xyz-b.xyz);
                clr = a.w;

        }
        //clr=c.w+b.w;
        h = min(h, L(b.xy,c.xy,u.xy));



        // h dist line
        // i dist curve

